/**
 * Options for the experimental affinity header API.
 */
export type GetAffinityHeadersOptions = {
    /**
     * The affinity ID to route this request to. Must contain 1 to 256 visible
     * ASCII characters, without spaces.
     */
    affinityId: string;
    /**
     * Whether to attach the current project's OIDC token. Enable only for a
     * trusted destination. Service-binding URLs do not require this option.
     * @default false
     */
    oidc?: boolean;
};
/**
 * Returns the affinity ID from the current invocation's
 * `x-vercel-affinity-id` header, or `undefined` when it is unavailable.
 *
 * This is an experimental API and may change without notice.
 *
 * @experimental
 * @example
 * ```js
 * import { unstable_getAffinityId } from '@vercel/functions';
 *
 * const affinityId = unstable_getAffinityId();
 * ```
 */
export declare function unstable_getAffinityId(): string | undefined;
/**
 * Returns request headers for invoking a Vercel Function with an explicit
 * affinity ID. Set `oidc: true` to include the current project's OIDC token;
 * service-binding URLs authenticate independently.
 *
 * This is an experimental API and may change without notice.
 *
 * The returned object can be passed to `fetch` or another HTTP client, or
 * combined with other headers. Enable OIDC only for functions you intend to
 * receive the project's token, and avoid forwarding it through redirects to
 * untrusted destinations.
 *
 * @param options The required affinity ID and optional OIDC setting.
 * @returns A plain object containing `x-vercel-affinity-id` and, when enabled,
 * `x-vercel-trusted-oidc-idp-token`.
 *
 * @experimental
 * @example
 * ```js
 * import { unstable_getAffinityHeaders } from '@vercel/functions';
 *
 * const headers = await unstable_getAffinityHeaders({
 *   affinityId: 'room:123',
 *   oidc: true,
 * });
 *
 * const response = await fetch('https://my-project.vercel.app/api/actor', {
 *   method: 'POST',
 *   headers: { ...headers, 'content-type': 'application/json' },
 *   body: JSON.stringify({ action: 'join' }),
 *   redirect: 'error',
 * });
 * ```
 */
export declare function unstable_getAffinityHeaders(options: GetAffinityHeadersOptions): Promise<Record<string, string>>;
